package python

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// testdata/coverage_globs.json holds coverage.py's own answers (version in the
// file), generated by scripts/generate_coverage_glob_cases.py. Run it again
// after changing the cases or upgrading coverage. This test never runs
// coverage.py.
type globCases struct {
	CoverageVersion string `json:"coverage_version"`
	Cases           []struct {
		Pattern string `json:"pattern"`
		Path    string `json:"path"`
		Match   *bool  `json:"match"`
	} `json:"cases"`
}

func TestCoveragePatternsAgreeWithCoveragePy(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "coverage_globs.json"))
	if err != nil {
		t.Fatal(err)
	}
	var table globCases
	if err := json.Unmarshal(data, &table); err != nil {
		t.Fatal(err)
	}
	if table.CoverageVersion == "" || len(table.Cases) == 0 {
		t.Fatalf("empty oracle table: %+v", table)
	}
	root := t.TempDir()
	rejected := map[string]bool{}
	for _, tc := range table.Cases {
		pattern := strings.ReplaceAll(tc.Pattern, "{root}", root)
		name := fmt.Sprintf("coverage %s: %q on %q", table.CoverageVersion, tc.Pattern, tc.Path)
		scope, err := scopeWithInclude(t, root, pattern)
		if tc.Match == nil {
			if rejected[tc.Pattern] {
				continue
			}
			rejected[tc.Pattern] = true
			if err == nil {
				t.Errorf("%s: coverage.py rejects the pattern, repoctl accepted it", name)
			}
			continue
		}
		if err != nil {
			t.Errorf("%s: repoctl rejected a pattern coverage.py accepts: %v", name, err)
			continue
		}
		if got := scope.includes(tc.Path); got != *tc.Match {
			t.Errorf("%s: repoctl %v, coverage.py %v", name, got, *tc.Match)
		}
	}
}

func scopeWithInclude(t *testing.T, root, pattern string) (coverageScope, error) {
	t.Helper()
	config := fmt.Sprintf("[tool.coverage.run]\ninclude = [%q]\n", pattern)
	if err := os.WriteFile(filepath.Join(root, "pyproject.toml"), []byte(config), 0o600); err != nil {
		t.Fatal(err)
	}
	return readCoverageScope(root)
}
